// Generate an AES-256 key from Qrypt quantum entropy and verify it with AES-256-GCM.
import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";

process.loadEnvFile(".env");

const apiKey = process.env.QRYPT_API_KEY;
if (!apiKey) {
  console.error("QRYPT_API_KEY is not set in .env");
  process.exit(1);
}

const baseUrl = process.env.QRYPT_BASE_URL ?? "https://api-eus.qrypt.com";

async function fetchEntropy(sizeKiB = 1) {
  const res = await fetch(`${baseUrl}/api/v1/quantum-entropy?size=${sizeKiB}`, {
    headers: { Authorization: `Bearer ${apiKey}` },
  });

  if (!res.ok) {
    const hints = {
      400: "size must be between 1 and 512 (KiB)",
      401: "Authorization header missing, malformed, or token expired",
      403: "token invalid or monthly quota exhausted",
      429: "rate limited; wait at least 10 seconds before retrying",
    };
    const hint = hints[res.status] ?? "service busy or erroring; try again later";
    throw new Error(`Qrypt API returned ${res.status}: ${hint}`);
  }

  const body = await res.json();
  return Buffer.from(body.random[0], "base64");
}

const entropy = await fetchEntropy(1);
const key = entropy.subarray(0, 32);

// Round-trip a test message to confirm the key works for AES-256-GCM.
const iv = randomBytes(12);
const message = "Hello from Qrypt quantum entropy!";

const cipher = createCipheriv("aes-256-gcm", key, iv);
const ciphertext = Buffer.concat([cipher.update(message, "utf8"), cipher.final()]);
const tag = cipher.getAuthTag();

const decipher = createDecipheriv("aes-256-gcm", key, iv);
decipher.setAuthTag(tag);
const plaintext = Buffer.concat([decipher.update(ciphertext), decipher.final()]).toString("utf8");

console.log(`Entropy received: ${entropy.length} bytes`);
console.log(`AES-256 key length: ${key.length * 8} bits`);
console.log(`Ciphertext (hex): ${ciphertext.toString("hex")}`);
console.log(`Round-trip OK: ${plaintext === message}`);

